// MaxEco Energy & Tech - Official Logo Assets (Base64 Data URIs)
// Provides 100% offline, zero-CORS logo rendering across Invoices, Quotations, Vouchers, and ERP UI.

const LOGO_EMBLEM_DATA_URI = "data:image/png;base64,";
const LOGO_WORDMARK_DATA_URI = "data:image/png;base64,";

if (typeof window !== 'undefined') {
  window.LOGO_EMBLEM_DATA_URI = LOGO_EMBLEM_DATA_URI;
  window.LOGO_WORDMARK_DATA_URI = LOGO_WORDMARK_DATA_URI;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    LOGO_EMBLEM_DATA_URI,
    LOGO_WORDMARK_DATA_URI
  };
}
